// Memory mit Tier-Emojis (nur Spiel-API, keine Importe).
// 12 verdeckte Karten (6 Paare), 4 Spalten x 3 Reihen. Cursor mit Pfeilen oder Steuerkreuz, Feuer deckt auf.
// Hinweis zu Haekchen: h3 (Fotos der Enkel) ist nicht machbar, da es auf der Plattform keine Fotos gibt.
// Ersatz sind Tier-Emojis als Figuren.
// h7: Unter dem Raster gibt es den Knopf "Neues Spiel". Der Cursor erreicht ihn per down von der unteren Reihe
// (Index 12). Feuer auf dem Knopf mischt die Karten neu und setzt den Spielzustand zurueck.
// Layout-Hinweis: Mit x=22 ragt das Raster 2 px ueber den Rand (22 + 4*76 + 3*12 = 362 > 360),
// deshalb startet es bei x=20 (20 .. 340 + 20 = 360 genau passend).

const ANIMALS = ["🐘", "🦊", "🐻", "🐰", "🐥", "🐢"];
const CELL = 76, GAP = 12, X0 = 20, Y0 = 108;
const BTN = 12; // Cursor-Index des Knopfes "Neues Spiel"

export default {
  title: "Memory mit Tier-Emojis",
  controls: ["left", "right", "up", "down", "fire"],
  lives: 3,

  init(g) {
    return newState(g);
  },

  update(s, input, g) {
    // Zeitlimit: nach 3600 Frames ist Schluss
    if (g.frame >= 3600) { g.gameOver(); return; }

    // Cursor bewegen: ein Schritt, danach 8 Frames Pause
    if (s.cool > 0) s.cool -= 1;
    const c = s.cursor;
    if (s.cool === 0) {
      let moved = false;
      if (c.i < 12) {
        const col = c.i % 4;
        const row = Math.floor(c.i / 4);
        if (input.left && col > 0) { c.i -= 1; moved = true; }
        else if (input.right && col < 3) { c.i += 1; moved = true; }
        else if (input.up && row > 0) { c.i -= 4; moved = true; }
        else if (input.down && row < 2) { c.i += 4; moved = true; }
        else if (input.down && row === 2) { c.i = BTN; moved = true; }
      } else {
        if (input.up) { c.i = 10; moved = true; }
      }
      if (moved) s.cool = 8;
    }

    // Zwei offene Karten: nach 40 Frames vergleichen
    if (s.flipped.length === 2) {
      s.wait -= 1;
      if (s.wait <= 0) {
        const a = s.cards[s.flipped[0]];
        const b = s.cards[s.flipped[1]];
        if (a.emoji === b.emoji) {
          a.done = true; b.done = true;
          g.addScore(10);
          g.sound("coin");
        } else {
          a.open = false; b.open = false;
          g.sound("hurt");
          g.loseLife();
        }
        s.flipped = [];
        if (s.cards.every((k) => k.done)) {
          g.addScore(50);
          g.sound("win");
          g.win();
          return;
        }
      }
    }

    if (input.firePressed) {
      // Knopf "Neues Spiel": Karten neu mischen
      if (c.i === BTN) {
        const fresh = newState(g);
        s.cards = fresh.cards;
        s.cursor = fresh.cursor;
        s.cursor.i = BTN;
        s.flipped = fresh.flipped;
        s.wait = fresh.wait;
        s.cool = fresh.cool;
        g.sound("pop");
        return;
      }
      // Karte am Cursor aufdecken
      if (s.flipped.length < 2) {
        const card = s.cards[c.i];
        if (!card.open && !card.done) {
          card.open = true;
          s.flipped.push(c.i);
          if (s.flipped.length === 2) s.wait = 40;
        }
      }
    }
  },

  draw(s, d, g) {
    d.clear("cream");
    for (let i = 0; i < 12; i++) {
      const col = i % 4;
      const row = Math.floor(i / 4);
      const x = X0 + col * (CELL + GAP);
      const y = Y0 + row * (CELL + GAP);
      // Cursor: roter Rahmen unter der Karte
      if (s.cursor.i === i) d.rect(x - 4, y - 4, CELL + 8, CELL + 8, "red", { round: 14 });
      const card = s.cards[i];
      const shown = card.open || card.done;
      d.rect(x, y, CELL, CELL, shown ? "cream" : "yellow", { round: 10, shadow: true, line: true });
      if (shown) d.emoji(card.emoji, x + CELL / 2, y + CELL / 2, 40);
    }
    // Knopf "Neues Spiel" unter dem Raster
    const bx = 100, by = 380, bw = 160, bh = 44;
    if (s.cursor.i === BTN) d.rect(bx - 4, by - 4, bw + 8, bh + 8, "red", { round: 16 });
    d.rect(bx, by, bw, bh, "yellow", { round: 12, shadow: true, line: true });
    d.text("Neues Spiel", 180, by + 14, { size: 18, color: "ink", align: "center" });
    d.text("Pfeile: wählen · Feuer: aufdecken", 180, 470, { size: 14, color: "ink", align: "center" });
  }
};

function newState(g) {
  const deck = [];
  for (const e of ANIMALS) { deck.push(e); deck.push(e); }
  // Fisher-Yates mit g.randInt
  for (let i = deck.length - 1; i > 0; i--) {
    const j = g.randInt(0, i);
    const t = deck[i]; deck[i] = deck[j]; deck[j] = t;
  }
  const cards = deck.map((e) => ({ emoji: e, open: false, done: false }));
  return { cards: cards, cursor: { i: 0 }, flipped: [], wait: 0, cool: 0 };
}

// Segelboot-Angriff (nur Spiel-API, keine Importe).
// Hinweis zur Haekchenliste: [h7] "Space Invaders" ist ein geschuetzter Markenname und fehlt. Ersatz: eigener Titel Segelboot-Angriff.
// Das Floss wirft Wasserbomben, die Segelboote werfen Kugeln. Keine Gewalt gegen Menschen.
export default {
  title: "Segelboot-Angriff",
  controls: ["left", "right", "fire"],
  lives: 3,

  init(g) {
    const boats = fleet(g, 1);
    return {
      raft: { x: 160, y: 580, w: 40, h: 28 },
      bombs: [],
      balls: [],
      boats: boats,
      start: boats.length,
      dir: 1,
      cool: 0,
      safe: 0
    };
  },

  update(s, input, g) {
    const raft = s.raft;
    if (input.left) raft.x -= 4;
    if (input.right) raft.x += 4;
    raft.x = g.clamp(raft.x, 4, g.W - raft.w - 4);

    if (s.cool > 0) s.cool -= 1;
    if (s.safe > 0) s.safe -= 1;

    // Schiessen: Wasserbombe nach oben
    if ((input.firePressed || input.fire) && s.cool === 0 && s.bombs.length < 3) {
      s.bombs.push({ x: raft.x + raft.w / 2, y: raft.y, r: 7 });
      s.cool = 14;
      g.sound("shoot");
    }
    for (const b of s.bombs) b.y -= 8;
    s.bombs = s.bombs.filter((b) => b.y > g.TOP);

    // Flotte: seitwaerts, am Rand umkehren und eine Reihe tiefer
    const speed = 0.5 + 0.2 * g.level + (s.start - s.boats.length) * 0.04;
    let edge = false;
    for (const b of s.boats) {
      b.x += s.dir * speed;
      if (b.x < 6 || b.x + b.w > g.W - 6) edge = true;
    }
    if (edge) {
      s.dir = -s.dir;
      for (const b of s.boats) {
        b.x += s.dir * speed;
        b.y += 14;
      }
    }

    // Treffer Bombe gegen Boot
    for (const bomb of s.bombs) {
      for (const boat of s.boats) {
        if (!boat.sunk && g.hit(bomb, boat)) {
          boat.sunk = true;
          bomb.y = -100;
          g.addScore(10 * g.level);
          g.sound("pop");
          break;
        }
      }
    }
    s.boats = s.boats.filter((b) => !b.sunk);
    s.bombs = s.bombs.filter((b) => b.y > g.TOP);

    // Boote werfen Kugeln
    if (s.boats.length > 0 && g.random() < 0.012 + 0.006 * g.level) {
      const b = s.boats[g.randInt(0, s.boats.length - 1)];
      s.balls.push({ x: b.x + b.w / 2, y: b.y + b.h, r: 5 });
    }
    for (const c of s.balls) c.y += 2.5 + 0.4 * g.level;
    s.balls = s.balls.filter((c) => c.y < g.H + 10);

    // Treffer Kugel gegen Floss
    if (s.safe === 0 && s.balls.some((c) => g.hit(c, raft))) {
      s.balls = [];
      s.safe = 60;
      g.sound("hurt");
      g.loseLife();
    }

    // Ein Boot hat die Flosshoehe erreicht
    if (s.boats.some((b) => b.y + b.h >= raft.y)) {
      g.gameOver();
      return;
    }

    // Alle Boote versenkt: schwerere Flotte
    if (s.boats.length === 0) {
      g.nextLevel();
      g.sound("level");
      s.boats = fleet(g, g.level);
      s.start = s.boats.length;
      s.balls = [];
      s.dir = 1;
    }
  },

  draw(s, d, g) {
    d.clear("cream");
    for (let y = 120; y < g.H; y += 60) {
      const wave = (g.frame >> 3) % 6;
      d.line(0, y + wave, g.W, y + wave, "yellow", 2);
    }
    for (const b of s.boats) d.emoji("⛵", b.x + b.w / 2, b.y + b.h / 2, 30);
    for (const c of s.balls) d.circle(c.x, c.y, c.r, "ink");
    for (const b of s.bombs) d.circle(b.x, b.y, b.r, "yellow", { line: true });
    if (s.safe === 0 || (g.frame >> 2) % 2 === 0) {
      d.rect(s.raft.x + s.raft.w / 2 - 2, s.raft.y - 16, 4, 18, "ink");
      d.rect(s.raft.x, s.raft.y + 8, s.raft.w, s.raft.h - 8, "red", { round: 6, shadow: true, line: true });
    }
  }
};

function fleet(g, level) {
  const out = [];
  const rows = Math.min(2 + level, 5);
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < 6; c++) {
      out.push({ x: 20 + c * 52, y: g.TOP + 20 + r * 42, w: 34, h: 30, sunk: false });
    }
  }
  return out;
}

