// Memory mit Tieren (nur Spiel-API, keine Importe). 12 verdeckte Karten, 6 Tier-Paare.
// Steuerung: Richtungen bewegen den Cursor, fire deckt die Karte unter dem Cursor auf.
const SYMS = ["🐶", "🐱", "🐸", "🦊", "🐼", "🐵"];
const CARD_W = 90, CARD_H = 110, GAP = 12, X0 = 33, Y0 = 78;
const SHOW_TIME = 40, MOVE_COOLDOWN = 8, LIMIT = 3300;

export default {
  title: "Memory mit Tieren",
  controls: ["left", "right", "up", "down", "fire"],
  lives: 3,

  init(g) {
    return {
      cards: deal(g),
      cursor: { c: 0, r: 0 },
      first: -1,
      second: -1,
      wait: 0,
      time: 0,
      moves: 0,
      mv: 0
    };
  },

  update(s, input, g) {
    s.time += 1;
    if (s.time >= LIMIT) { g.gameOver(); return; }
    if (s.mv > 0) s.mv -= 1;

    if (s.wait > 0) {
      s.wait -= 1;
      if (s.wait === 0) resolve(s, g);
      return;
    }

    const dc = input.left ? -1 : input.right ? 1 : 0;
    const dr = input.up ? -1 : input.down ? 1 : 0;
    if ((dc !== 0 || dr !== 0) && s.mv === 0) {
      s.cursor.c = (s.cursor.c + dc + 3) % 3;
      s.cursor.r = (s.cursor.r + dr + 4) % 4;
      s.mv = MOVE_COOLDOWN;
    }

    if (input.firePressed) {
      flip(s, g, s.cursor.r * 3 + s.cursor.c);
    }
  },

  draw(s, d, g) {
    d.clear("cream");
    for (let i = 0; i < s.cards.length; i++) {
      const card = s.cards[i];
      if (!card.open && !card.matched) {
        d.rect(card.x, card.y, CARD_W, CARD_H, "yellow", { round: 10, shadow: true, line: true });
        d.text("?", card.x + CARD_W / 2, card.y + CARD_H / 2 - 20, { size: 40, color: "ink", align: "center" });
      } else {
        d.rect(card.x, card.y, CARD_W, CARD_H, "cream", { round: 10, line: true });
        d.emoji(card.sym, card.x + CARD_W / 2, card.y + CARD_H / 2, 52);
        if (card.matched) d.rect(card.x + 4, card.y + 4, CARD_W - 8, CARD_H - 8, "red", { round: 8, line: true });
      }
    }
    const cur = s.cards[s.cursor.r * 3 + s.cursor.c];
    d.rect(cur.x - 4, cur.y - 4, CARD_W + 8, CARD_H + 8, "red", { round: 12, line: true });

    const secs = Math.max(0, Math.round((LIMIT - s.time) / 60));
    d.text("Zeit: " + secs + " s", g.W / 2, 600, { size: 20, color: "ink", align: "center" });
  }
};

function deal(g) {
  const syms = [];
  for (let i = 0; i < 12; i++) syms.push(SYMS[Math.floor(i / 2)]);
  for (let i = 11; i >= 1; i--) {
    const j = g.randInt(0, i);
    const tmp = syms[i];
    syms[i] = syms[j];
    syms[j] = tmp;
  }
  const cards = [];
  for (let i = 0; i < 12; i++) {
    const c = i % 3, r = Math.floor(i / 3);
    cards.push({
      id: i,
      sym: syms[i],
      open: false,
      matched: false,
      x: X0 + c * (CARD_W + GAP),
      y: Y0 + r * (CARD_H + GAP)
    });
  }
  return cards;
}

function flip(s, g, idx) {
  const card = s.cards[idx];
  if (card.matched || card.open) return;
  card.open = true;
  g.sound("jump");
  if (s.first < 0) {
    s.first = idx;
  } else {
    s.second = idx;
    s.moves += 1;
    s.wait = SHOW_TIME;
  }
}

function resolve(s, g) {
  const i1 = s.first, i2 = s.second;
  s.first = -1;
  s.second = -1;
  const a = s.cards[i1], b = s.cards[i2];
  if (a.sym === b.sym) {
    a.matched = true;
    b.matched = true;
    g.addScore(20);
    g.sound("coin");
    if (s.cards.every((c) => c.matched)) {
      g.addScore(50);
      g.sound("win");
      g.win();
    }
  } else {
    a.open = false;
    b.open = false;
    g.sound("hurt");
    g.loseLife();
  }
}

