const SYMS = ["🐶", "🐱", "🐸", "🦊", "🐼", "🐵"];
const CARD_W = 90, CARD_H = 110, GAP = 12, X0 = 33, Y0 = 78;
const SHOW_TIME = 40, MOVE_COOLDOWN = 8, LIMIT = 3300;

export default {
  title: "Memory mit Tieren",
  controls: ["left", "right", "up", "down", "fire"],
  lives: 3,

